CREATE TEMPORARY VIEW vitem_list_${grass_region_without_quote} AS
select vitem_id
     ,exp_tag
from(
        SELECT vitem_id
        FROM srdi_mart.dim_sr_data_warehouse_vsku_model_mapping_hf
        where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
        group by 1
) a
lateral view explode(array('T4')) b as exp_tag -- 按照实验策略数量，进行维表复制拷贝
;
--sql_divide_splitter--

set last_partition_${grass_region_without_quote} = (
    select
    max(time_str)
    from(
        SELECT
        concat(regional_date,'_',if(regional_hour<10,concat('0',regional_hour),regional_hour)) as  time_str
        FROM srdi_mart.dim_sr_data_warehouse_vsku_replace_vitem_metrics_hf
        where grass_region in (${grass_region}) and regional_date between date_sub(${regional_date}, 6) and ${regional_date}
        group by regional_date,regional_hour
    ) a
    where time_str<concat(${regional_date},'_',if(${regional_hour}<10,concat('0',${regional_hour}),${regional_hour}))
);
--sql_divide_splitter--

CREATE TEMPORARY VIEW last_vitem_${grass_region_without_quote} AS
SELECT
    exp_tag
     ,vitem_id
     ,version_date
FROM srdi_mart.dim_sr_data_warehouse_vsku_replace_vitem_metrics_hf
where grass_region in (${grass_region}) and regional_date = split(${last_partition_${grass_region_without_quote}},'_')[0]
  and regional_hour = cast(split(${last_partition_${grass_region_without_quote}},'_')[1] as int)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW accumulated_vitem_${grass_region_without_quote} AS
select coalesce(a.exp_tag, b.exp_tag) exp_tag
    ,coalesce(a.vitem_id, b.vitem_id) vitem_id
    ,coalesce(a.version_date, replace(${regional_date}, '-', '')) version_date
from last_vitem_${grass_region_without_quote} a
FULL OUTER JOIN vitem_list_${grass_region_without_quote} b
on a.exp_tag = b.exp_tag
and a.vitem_id = b.vitem_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW nd_metrics_${grass_region_without_quote} AS
SELECT exp_tag
     ,vitem_id
     ,version_date
     ,imp_cnt
     ,click_cnt
FROM srdi_mart.dws_sr_data_warehouse_vsku_replace_vitem_hourly_nd
where grass_region in (${grass_region}) and regional_date=${regional_date} and regional_hour=${regional_hour}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_metrics_${grass_region_without_quote} AS
select vitem_id
     ,exp_tag
     ,version_date
     ,sum(imp_cnt) as exp_imp_cnt_nd
     ,sum(click_cnt) as exp_click_cnt_nd
from nd_metrics_${grass_region_without_quote}
where exp_tag like 'T%'
group by 1,2,3
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW control_metrics_${grass_region_without_quote} AS
select vitem_id
     ,sum(imp_cnt) as control_imp_cnt_nd
     ,sum(click_cnt) as control_click_cnt_nd
from nd_metrics_${grass_region_without_quote}
where exp_tag = 'C1'
group by 1
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW realtime_metrics_${grass_region_without_quote} AS
SELECT *
FROM paimon.srdi_mart.dws_sr_data_warehouse_vsku_replace_vitem_realtime_1d
where grass_region in (${grass_region})
  and regional_date between date_sub(${regional_date},6) and ${regional_date}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_3d_metrics_${grass_region_without_quote} AS
SELECT exp_tag
     ,vitem_id
     ,version_date
     ,sum(case when regional_date >= date_sub(${regional_date},2) then imp_cnt else 0 end) exp_imp_cnt_3d
     ,sum(case when regional_date >= date_sub(${regional_date},2) then click_cnt else 0 end) exp_click_cnt_3d
     ,sum(imp_cnt) exp_imp_cnt_7d
     ,sum(click_cnt) exp_click_cnt_7d
FROM realtime_metrics_${grass_region_without_quote}
where exp_tag like 'T%'
group by 1,2,3
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW control_3d_metrics_${grass_region_without_quote} AS
SELECT vitem_id
     ,sum(case when regional_date >= date_sub(${regional_date},2) then imp_cnt else 0 end) control_imp_cnt_3d
     ,sum(case when regional_date >= date_sub(${regional_date},2) then click_cnt else 0 end) control_click_cnt_3d
     ,sum(imp_cnt) control_imp_cnt_7d
     ,sum(click_cnt) control_click_cnt_7d
FROM realtime_metrics_${grass_region_without_quote}
where exp_tag like 'C%'
group by 1
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW item_feature_${grass_region_without_quote} AS
select itemid
     ,ctr7 as vitem_ctr_7d_rcmd
     ,cr7 as vitem_cr_7d_rcmd
     ,ctcvr7 as vitem_ctcvr_7d_rcmd
     ,impr_7d_cnt as vitem_imp_7d_rcmd
     ,click_7d_cnt as vitem_click_7d_rcmd
from srdi_mart.dws_fp_rcmd_item_feature
where country = ${grass_region}
and dt = data_infra.max_pt('srdi_mart.dws_fp_rcmd_item_feature', 'dt', "country=${grass_region} and dt<${regional_date}")
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_vsku_replace_vitem_metrics_hf
partition(grass_region = ${grass_region}, regional_date=${regional_date}, regional_hour=${regional_hour})
SELECT a.vitem_id
     ,a.exp_tag
     ,a.version_date

     ,coalesce(b.exp_imp_cnt_nd,0) exp_imp_cnt_nd
     ,coalesce(b.exp_click_cnt_nd,0) exp_click_cnt_nd
     ,coalesce(c.control_imp_cnt_nd,0) control_imp_cnt_nd
     ,coalesce(c.control_click_cnt_nd,0) control_click_cnt_nd
     ,coalesce(d.exp_imp_cnt_3d,0) exp_imp_cnt_3d
     ,coalesce(d.exp_click_cnt_3d,0) exp_click_cnt_3d
     ,coalesce(d.exp_imp_cnt_7d,0) exp_imp_cnt_7d
     ,coalesce(d.exp_click_cnt_7d,0) exp_click_cnt_7d
     ,coalesce(exp_click_cnt_nd,0)/exp_imp_cnt_nd as exp_ctr_nd
     ,coalesce(control_click_cnt_nd,0)/control_imp_cnt_nd as control_ctr_nd

     ,coalesce(exp_click_cnt_3d,0)/exp_imp_cnt_3d exp_ctr_3d
     ,coalesce(exp_click_cnt_7d,0)/exp_imp_cnt_7d exp_ctr_7d
     ,coalesce(e.control_imp_cnt_3d,0) control_imp_cnt_3d
     ,coalesce(e.control_imp_cnt_7d,0) control_imp_cnt_7d
     ,coalesce(e.control_click_cnt_3d,0) control_click_cnt_3d
     ,coalesce(e.control_click_cnt_7d,0) control_click_cnt_7d
     ,coalesce(control_click_cnt_3d,0)/control_imp_cnt_3d control_ctr_3d
     ,coalesce(control_click_cnt_7d,0)/control_imp_cnt_7d control_ctr_7d

     ,f.vitem_ctr_7d_rcmd
     ,f.vitem_cr_7d_rcmd
     ,f.vitem_ctcvr_7d_rcmd
     ,f.vitem_imp_7d_rcmd
     ,f.vitem_click_7d_rcmd
FROM accumulated_vitem_${grass_region_without_quote} a
left join exp_metrics_${grass_region_without_quote} b
on a.vitem_id = b.vitem_id
and a.exp_tag = b.exp_tag
and a.version_date = b.version_date
left join control_metrics_${grass_region_without_quote} c
on a.vitem_id = c.vitem_id
left join exp_3d_metrics_${grass_region_without_quote} d
on a.vitem_id =d.vitem_id
and a.exp_tag =d.exp_tag
and a.version_date =d.version_date
left join control_3d_metrics_${grass_region_without_quote} e
on a.vitem_id =e.vitem_id
left join item_feature_${grass_region_without_quote} f
on a.vitem_id = f.itemid
;
